package com.casystem.onboarding.controller;import com.casystem.onboarding.model.Document;import com.casystem.onboarding.repository.DocumentRepository;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;@RestController @RequestMapping("/api/documents") @CrossOrigin(origins="*") public class DocumentController{private final DocumentRepository docs;private final TokenService tokens;private final CryptoService crypto;private final AuditService audit;public DocumentController(DocumentRepository d,TokenService t,CryptoService c,AuditService a){docs=d;tokens=t;crypto=c;audit=a;}@GetMapping public List<Map<String,Object>> list(@RequestHeader("Authorization")String h){Long uid=tokens.userId(h);return docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(uid).stream().map(d->{Map<String,Object>m=new LinkedHashMap<>();m.put("id",d.getId());m.put("fileName",d.getFileName());m.put("contentType",d.getContentType());m.put("createdAt",d.getCreatedAt());return m;}).toList();}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public Map<String,Object> upload(@RequestHeader("Authorization")String h,@RequestParam("file")MultipartFile f,HttpServletRequest req)throws Exception{Long uid=tokens.userId(h);if(f.isEmpty()||f.getSize()>5_000_000)throw new IllegalArgumentException("Archivo vacío o mayor a 5 MB");Document d=new Document();d.setUserId(uid);d.setFileName(f.getOriginalFilename());d.setContentType(f.getContentType()==null?"application/octet-stream":f.getContentType());d.setEncryptedContent(crypto.encryptBytes(f.getBytes()));docs.save(d);audit.log(uid,"Documento cargado: "+d.getFileName(),req.getRemoteAddr());return Map.of("message","Documento cargado","id",d.getId());}@GetMapping("/{id}")public ResponseEntity<byte[]> download(@RequestHeader("Authorization")String h,@PathVariable Long id,HttpServletRequest req){Long uid=tokens.userId(h);Document d=docs.findByIdAndUserIdAndDeletedFalse(id,uid).orElseThrow();audit.log(uid,"Documento consultado: "+d.getFileName(),req.getRemoteAddr());return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+d.getFileName().replace("\"","")+"\"").contentType(MediaType.parseMediaType(d.getContentType())).body(crypto.decryptBytes(d.getEncryptedContent()));}@PutMapping(value="/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public Map<String,Object> replace(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestParam("file")MultipartFile f,HttpServletRequest req)throws Exception{Long uid=tokens.userId(h);Document d=docs.findByIdAndUserIdAndDeletedFalse(id,uid).orElseThrow();if(f.isEmpty()||f.getSize()>5_000_000)throw new IllegalArgumentException("Archivo vacío o mayor a 5 MB");d.setFileName(f.getOriginalFilename());d.setContentType(f.getContentType()==null?"application/octet-stream":f.getContentType());d.setEncryptedContent(crypto.encryptBytes(f.getBytes()));docs.save(d);audit.log(uid,"Documento reemplazado: "+d.getFileName(),req.getRemoteAddr());return Map.of("message","Documento reemplazado");}@DeleteMapping("/{id}")public Map<String,String> delete(@RequestHeader("Authorization")String h,@PathVariable Long id,HttpServletRequest req){Long uid=tokens.userId(h);Document d=docs.findByIdAndUserIdAndDeletedFalse(id,uid).orElseThrow();d.setDeleted(true);docs.save(d);audit.log(uid,"Documento eliminado lógicamente: "+d.getFileName(),req.getRemoteAddr());return Map.of("message","Documento eliminado");}}